    gocpp::error chtimesat(syscall::Handle dirfd, gocpp::string name, mocklib::Date atime, mocklib::Date mtime)
    {
        gocpp::Defer defer;
        try
        {
            auto [h, err] = windows::Openat(dirfd, name, syscall::O_CLOEXEC | windows::O_NOFOLLOW_ANY | windows::O_WRITE_ATTRS, 0);
            if(err == syscall::go_ELOOP || err == syscall::go_ENOTDIR)
            {
                if(auto [link, err] = readReparseLinkAt(dirfd, name); err == nullptr)
                {
                    return gocpp::error(errSymlink(link));
                }
            }
            if(err != nullptr)
            {
                return err;
            }
            defer.push_back([=]{ syscall::CloseHandle(h); });
            auto a = syscall::Filetime {};
            auto w = syscall::Filetime {};
            if(! rec::IsZero(gocpp::recv(atime)))
            {
                a = syscall::NsecToFiletime(rec::UnixNano(gocpp::recv(atime)));
            }
            if(! rec::IsZero(gocpp::recv(mtime)))
            {
                w = syscall::NsecToFiletime(rec::UnixNano(gocpp::recv(mtime)));
            }
            return syscall::SetFileTime(h, nullptr, & a, & w);
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

